//! Device capability claims cannot drift from code or outrun their evidence (#788).
//!
//! The provider matrix in AGENTS.md is generated by `tests/mcp_contract.rs`. Devices get the same
//! treatment: the device table is rendered from `capabilities_for`, the function the adapter
//! itself publishes, and a `hardware-verified` claim must point at a fixture directory that exists.
//!
//! Regenerate the table with:
//!
//! ```sh
//! UPDATE_AGENTS_DEVICES=1 cargo test --test device_claims
//! ```

use std::path::Path;

use unified_hifi_control::adapters::denonavr::{
    capabilities_for, READ_VERIFIED_MODELS, WRITE_VERIFIED_MODELS,
};
use unified_hifi_control::devices::{CapabilityEvidence, DeviceCapability};

const BEGIN: &str = "<!-- BEGIN GENERATED DEVICE CAPABILITIES (tests/device_claims.rs) -->";
const END: &str = "<!-- END GENERATED DEVICE CAPABILITIES -->";

fn cell(capability: &DeviceCapability) -> String {
    match (capability.supported, capability.evidence) {
        (false, _) => "⛔ until range read".to_string(),
        (true, CapabilityEvidence::HardwareVerified) => "✅ hardware-verified".to_string(),
        (true, CapabilityEvidence::ImplementationDerived) => "🚧 implemented, #788".to_string(),
    }
}

fn render() -> String {
    let mut out = String::new();
    out.push_str(BEGIN);
    out.push_str("\n\n");
    out.push_str(
        "| Model | Observe | Volume | Mute | Power | Input select |\n|---|---|---|---|---|---|\n",
    );
    for (model, _) in READ_VERIFIED_MODELS {
        let claims = capabilities_for(model, true);
        out.push_str(&format!(
            "| Marantz {model} | {} | {} | {} | {} | {} |\n",
            cell(&claims.observe),
            cell(&claims.volume),
            cell(&claims.mute),
            cell(&claims.power),
            cell(&claims.input_select),
        ));
    }
    let other = capabilities_for("(any other Denon/Marantz model)", true);
    out.push_str(&format!(
        "| Other Denon / Marantz | {} | {} | {} | {} | {} |\n",
        cell(&other.observe).replace("✅ hardware-verified", "✅"),
        cell(&other.volume),
        cell(&other.mute),
        cell(&other.power),
        cell(&other.input_select),
    ));
    out.push_str(
        "\n✅ hardware-verified: exercised on the units with captured fixtures · 🚧 implemented \
         but not yet exercised on hardware (tracked by #788) · ⛔ refused while the condition \
         holds\n\n",
    );
    let sr6008 = capabilities_for("SR6008", true);
    for (name, claim) in [
        ("observe", &sr6008.observe),
        ("volume", &sr6008.volume),
        ("mute", &sr6008.mute),
        ("power", &sr6008.power),
        ("input select", &sr6008.input_select),
    ] {
        out.push_str(&format!("- **SR6008 / {name}** — {}\n", claim.detail));
    }
    out.push('\n');
    out.push_str(END);
    out
}

/// A `hardware-verified` claim must name a fixture directory that exists and documents itself.
#[test]
fn hardware_verified_claims_point_at_existing_captures() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    for (model, directory) in READ_VERIFIED_MODELS.iter().chain(WRITE_VERIFIED_MODELS) {
        let directory = root.join(directory);
        assert!(
            directory.join("README.md").is_file(),
            "{model} is claimed hardware-verified, but {} has no README describing the capture",
            directory.display()
        );
        let captures = std::fs::read_dir(&directory)
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| entry.path().is_dir())
            .count();
        assert!(captures > 0, "{model}: no per-unit capture directories");
    }
}

/// Until a write capture exists, no write path may claim hardware verification — the catalog's
/// rule: implementation- or source-derived support never becomes a hardware-tested claim.
#[test]
fn write_claims_are_not_hardware_verified_without_a_write_capture() {
    for (model, _) in READ_VERIFIED_MODELS {
        if WRITE_VERIFIED_MODELS.iter().any(|(m, _)| m == model) {
            continue;
        }
        let claims = capabilities_for(model, true);
        for claim in [
            &claims.volume,
            &claims.mute,
            &claims.power,
            &claims.input_select,
        ] {
            assert_eq!(
                claim.evidence,
                CapabilityEvidence::ImplementationDerived,
                "{model}: {}",
                claim.detail
            );
        }
    }
}

/// A unit reached without its range must not advertise volume.
#[test]
fn volume_is_not_advertised_without_a_known_range() {
    assert!(!capabilities_for("SR6008", false).volume.supported);
}

#[test]
fn agents_md_device_table_matches_the_derived_claims() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("AGENTS.md");
    let agents = std::fs::read_to_string(&path).unwrap();
    let start = agents
        .find(BEGIN)
        .expect("AGENTS.md has no generated device table");
    let end = agents
        .find(END)
        .expect("generated device table is unterminated")
        + END.len();
    let rendered = render();
    if agents[start..end] != rendered {
        if std::env::var("UPDATE_AGENTS_DEVICES").as_deref() == Ok("1") {
            let updated = format!("{}{}{}", &agents[..start], rendered, &agents[end..]);
            std::fs::write(&path, updated).unwrap();
            return;
        }
        panic!(
            "AGENTS.md device table is stale. Regenerate with \
             UPDATE_AGENTS_DEVICES=1 cargo test --test device_claims\n\nexpected:\n{rendered}"
        );
    }
}
